import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"周易口诀义 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"周易口诀义 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/004.md","filePath":"zh/classics/koujueyi/004.md"}'),r={name:"zh/classics/koujueyi/004.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>彖曰：至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。牝马地类，行地无疆，柔顺利贞。君子攸行，先迷失道，后顺得常。西南得朋，乃与类行。东北丧朋，乃终有庆。安贞之吉，应地无疆。</p><p>象曰：地势坤，君子以厚德载物。初六，履霜，坚冰至。</p><p>象曰：「履霜坚冰」，阴始凝也，驯致其道，至坚冰也。</p><p>六二，直方大，不习无不利。</p><p>象曰：六二之动，直以方也。「不习无不利」，地道光也。六三，含章可贞，或从王事，无成有终。</p><p>象曰：「含章可贞」，以时发也；「或从王事」，知光大也。六四，括囊，无咎无誉。</p><p>象曰：「括囊无咎」，慎不害也。六五，黄裳元吉。</p><p>象曰：「黄裳元吉」，文在中也。</p><p>上六，龙战于野，其血玄黄。</p><p>象曰：「龙战于野」，其道穷也。用六，利永贞。</p><p>象曰：用六「永贞」，以大终也。</p><p>解读</p><p>坤，元亨，利牝马之贞。坤，地也，顺也，地之为体，能生始万物，各得亨通，故有「元亨」也。「利牝马之贞」者，地体必以柔顺而为其正，故借牝马而为其贞，牝马是柔顺之物，所以将马为喻，马行地能穷其边疆，是明地有广之德，故先儒云：「在天为龙，在地为马。」「君子有攸往」者，明君子但以柔顺为德，又复行其贞正，故利有所往也。「先迷，后得主利」者，夫阴之为道，不可首倡居先，若在阳气之先，则不能发生滋育，必待阳而为首，所以「后得主利」也。犹如臣子处君之朝，顺事主终，在家为迷，得主为利也。「西南得朋」者，西南坤位，是阴也，今以阴就阴，是「得朋」也。「东北丧朋，安贞吉」者，东北艮位，为阳也，西南阴类，往虽得朋，必无所利，若能丧失朋而就阳，则获安静贞正之吉。以人事明之，犹人臣离其党，入君之朝，女子舍其家，入夫之室是也。</p><p>象曰：「地势坤，君子以厚德载物」者，天圆地方，是形不顺也，其势承顺天道之常，故曰「地势坤」也。君子当须以容厚为德，包载万物，象地之道广育也。</p><p>「初六，履霜，坚冰至」者，初六阴气之微，要假积渐以成其功，故引「履霜」以为其喻。且五月一阴爻始生，九月五阴始为霜降，至于十一月，乃至坚冰。此明祸福之由，积久乃显，所以防萌杜渐，慎终于始。故文言云：「臣弑其君，子弑其父，犹辨之不早辨也。」</p><p>「六二，直方、大，不习无不利」，六二居中得位，尽地之美，故有三德：「直、方、大」，生物不邪，「直」也；地体安厚，「方」也；无所不载，「大」也。既有斯德，尽地之善，故不假积习而「无不利」。施之于人，为臣忠，为子孝，与朋友信故也。</p><p>「六三含章可贞，或从王事，无成有终」者，六三既居上位，有造为阳之事者，含章美之德，待时而发，可以得贞之吉。既居臣体，不可先倡，「或从王事」者，言其不敢自专也；「无成有终」者，不敢居事之先，主成于物，惟顺君命而成其终。</p><p>「六四括囊，无咎无誉」者，括，结也；囊，所以盛物，喻人心藏智也。既是阴位，不可显发，亦犹不遇其时，闭而不用也，故曰「括囊」也。戒慎自守，不与物忤，故曰「无咎」也。德既不施，无声誉之美，故曰「无誉」也。</p><p>六五「黄裳，元吉」者，五是贵位，六以阴居之，是臣道极贵者也。黄是中之色也，裳是下之饰也。上衣比君，下裳法臣，六五既是臣体，不可比衣，故云「黄裳」，以表臣道黄中之美也。以文德居中，尽臣之善，故获「大吉」也。</p><p>「上六：龙战于野，其血玄黄」者，上六阴极似阳，故称「龙」也；阴既强盛，则侵于阳，故与阳气之龙交战也。战于卦外，故曰「野」也。阴阳俱伤，故有玄黄之色也。阳色玄，阴色黄也。「用六，利永贞」者，用总此六爻之义也。坤体柔顺，不可用之刚暴，故须永长贞正，则能广大而终也。乾吉在「无首」，坤利在「永贞」。</p>',21)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
